TArrayView<const FMjSensorTypeInfo> MjSensorTypeInfoTable()
{
	return GetSensorTypeInfoTable();
}

const FMjSensorTypeInfo& MjSensorTypeInfoFor(EMjSensorType Type)
{
	static const TMap<EMjSensorType, const FMjSensorTypeInfo*> ByType = [] {
		TMap<EMjSensorType, const FMjSensorTypeInfo*> Map;
		for (const FMjSensorTypeInfo& Info : GetSensorTypeInfoTable())
		{
			Map.Add(Info.Type, &Info);
		}
		return Map;
	}();
	if (const FMjSensorTypeInfo* const* Found = ByType.Find(Type))
	{
		return **Found;
	}
	return *ByType.FindChecked(EMjSensorType::Accelerometer);
}

const FMjSensorTypeInfo* MjSensorTypeInfoForTag(const FString& Tag)
{
	static const TMap<FString, const FMjSensorTypeInfo*> ByTag = [] {
		TMap<FString, const FMjSensorTypeInfo*> Map;
		for (const FMjSensorTypeInfo& Info : GetSensorTypeInfoTable())
		{
			Map.Add(FString(Info.Tag).ToLower(), &Info);
		}
		return Map;
	}();
	if (const FMjSensorTypeInfo* const* Found = ByTag.Find(Tag.ToLower()))
	{
		return *Found;
	}
	return nullptr;
}
